
  :root{
    --navy:#1B2A45;
    --navy-2:#22345F;
    --terracotta:#C1602E;
    --terracotta-dark:#A44E23;
    --gold:#D9A441;
    --cream:#FBF8F2;
    --sage:#EFF1EA;
    --white:#FFFFFF;
    --text-dim:#5B6472;
    --line:#E1DFD3;
    --radius:14px;
  }
  *{box-sizing:border-box; margin:0; padding:0;}
  html{scroll-behavior:smooth;}
  body{
    font-family:'Plus Jakarta Sans', sans-serif;
    color:var(--navy);
    background:var(--cream);
    -webkit-font-smoothing:antialiased;
  }
  img{max-width:100%; display:block;}
  a{color:inherit; text-decoration:none;}
  button{font-family:inherit; cursor:pointer; border:none;}
  .wrap{max-width:1200px; margin:0 auto; padding:0 28px;}
  .mono{font-family:'JetBrains Mono', monospace;}
  .eyebrow{
    font-family:'JetBrains Mono', monospace;
    font-size:11.5px; letter-spacing:0.12em; text-transform:uppercase;
    color:var(--terracotta); font-weight:600; margin-bottom:10px; display:block;
  }
  .eyebrow.on-dark{color:var(--gold);}
  h1,h2,h3{font-weight:800; line-height:1.1; color:var(--navy);}
  h1{font-size:clamp(32px,4.4vw,54px);}
  h2{font-size:clamp(24px,3vw,36px);}
  h3{font-size:18px;}
  p{color:var(--text-dim); line-height:1.6;}
  .btn{
    display:inline-flex; align-items:center; justify-content:center; gap:8px;
    padding:13px 26px; border-radius:999px; font-weight:700; font-size:14.5px;
    transition:transform 0.15s ease, box-shadow 0.15s ease; white-space:nowrap;
  }
  .btn-primary{background:var(--terracotta); color:#fff;}
  .btn-primary:hover{background:var(--terracotta-dark); transform:translateY(-1px);}
  .btn-outline{background:transparent; border:1.5px solid var(--navy); color:var(--navy);}
  .btn-outline:hover{background:var(--navy); color:#fff;}
  .btn-outline.light{border-color:rgba(255,255,255,0.5); color:#fff;}
  .btn-outline.light:hover{background:#fff; color:var(--navy);}
  .btn-sm{padding:9px 18px; font-size:13px;}
  .btn-block{width:100%;}

  /* ---------- NAV ---------- */
  header.site-nav{
    position:sticky; top:0; z-index:100;
    background:rgba(251,248,242,0.92); backdrop-filter:blur(10px);
    border-bottom:1px solid var(--line);
  }
  .nav-inner{display:flex; align-items:center; justify-content:space-between; padding:12px 28px; max-width:1200px; margin:0 auto; gap:20px;}
  .nav-logo{height:38px; cursor:pointer;}
  .nav-links{display:flex; align-items:center; gap:28px; font-size:14.5px; font-weight:600;}
  .nav-links a{cursor:pointer; padding:6px 0; border-bottom:2px solid transparent;}
  .nav-links a:hover, .nav-links a.active{border-bottom-color:var(--terracotta); color:var(--terracotta);}
  .nav-right{display:flex; align-items:center; gap:14px;}

  .lang-select-wrap{position:relative;}
  .lang-btn{
    display:flex; align-items:center; gap:6px; padding:8px 12px; border-radius:999px;
    border:1.5px solid var(--line); background:#fff; font-size:13px; font-weight:600; color:var(--navy);
  }
  .lang-menu{
    position:absolute; top:calc(100% + 8px); right:0; background:#fff; border:1px solid var(--line);
    border-radius:12px; box-shadow:0 20px 40px -12px rgba(27,42,69,0.25); width:220px;
    padding:8px; display:none; max-height:340px; overflow-y:auto; z-index:200;
  }
  .lang-menu.open{display:block;}
  .lang-option{
    display:flex; justify-content:space-between; align-items:center;
    padding:9px 12px; border-radius:8px; font-size:13.5px; cursor:pointer;
  }
  .lang-option:hover{background:var(--sage);}
  .lang-option.active{background:rgba(193,96,46,0.1); color:var(--terracotta); font-weight:700;}
  .lang-option .soon{font-size:10px; color:var(--text-dim); font-weight:500;}

  .mobile-toggle{display:none; font-size:22px; background:none;}

  @media (max-width:860px){
    .nav-links{display:none;}
    .mobile-toggle{display:block;}
  }

  /* ---------- HERO ---------- */
  .hero{
    position:relative; min-height:640px; display:flex; align-items:center;
    background-size:cover; background-position:center;
    overflow:hidden;
  }
  .hero::before{
    content:''; position:absolute; inset:0;
    background:linear-gradient(180deg, rgba(15,20,35,0.55) 0%, rgba(15,20,35,0.72) 55%, rgba(15,20,35,0.88) 100%);
  }
  .hero-content{position:relative; z-index:2; width:100%; padding:90px 28px 70px; max-width:1200px; margin:0 auto; text-align:center;}
  .hero-logo{max-width:440px; width:80%; margin:0 auto 22px; filter:drop-shadow(0 12px 30px rgba(0,0,0,0.35));}
  .hero-content h1{color:#fff; font-size:clamp(26px,3.4vw,40px); max-width:760px; margin:0 auto 16px; font-weight:700;}
  .hero-content p.sub{color:rgba(255,255,255,0.82); font-size:16px; max-width:600px; margin:0 auto 34px;}
  .hero-search{
    display:flex; align-items:center; gap:10px; background:#fff; border-radius:999px;
    padding:8px; max-width:600px; margin:0 auto 22px; box-shadow:0 20px 50px -15px rgba(0,0,0,0.5);
  }
  .hero-search input{
    flex:1; border:none; outline:none; padding:12px 18px; font-size:14.5px; font-family:inherit; color:var(--navy); background:transparent;
  }
  .hero-ctas{display:flex; gap:14px; justify-content:center; flex-wrap:wrap; margin-bottom:26px;}
  .hero-checks{display:flex; gap:22px; justify-content:center; flex-wrap:wrap; font-size:12.5px; color:rgba(255,255,255,0.75); font-weight:600;}
  .hero-checks span::before{content:'✓ '; color:var(--gold);}

  /* ---------- VISUAL HOME HERO v14 ---------- */
  .visual-home-hero{
    position:relative; width:100%; height:540px; min-height:540px; padding:0 !important; margin:0; box-sizing:border-box;
    background-image:url('data:image/png;base64,'); background-size:100% auto; background-repeat:no-repeat; background-position:center top;
    background-color:#f8f3e9; overflow:visible;
  }
  .visual-home-hero .visual-search::before{content:''; position:absolute; inset:0; border-radius:28px; background:#fff; z-index:-1;}
  .visual-home-hero .visual-search{
    position:absolute; left:18%; right:18%; top:460px; z-index:10;
    display:grid; grid-template-columns:1.55fr 1fr 1fr auto; align-items:stretch;
    gap:0; padding:8px; border-radius:28px; background:#fff;
    box-shadow:0 16px 38px rgba(15,32,55,.25);
  }
  .visual-search-field{min-width:0; display:flex; align-items:center; gap:8px; padding:7px 12px; border-right:1px solid rgba(27,42,69,.14);}
  .visual-search-field:last-of-type{border-right:0;}
  .visual-search-field .vs-icon{font-size:19px; flex:0 0 auto;}
  .visual-search-field label{display:block; font-size:12px; font-weight:800; color:var(--navy); margin-bottom:3px;}
  .visual-search-field input,.visual-search-field select{width:100%; border:0; outline:0; background:transparent; font-family:inherit; font-size:13px; color:#667085; min-width:0;}
  .visual-search-field input{padding:0;}
  .visual-search-field select{cursor:pointer; appearance:auto;}
  .visual-search .vs-explore{align-self:stretch; min-width:142px; padding:0 24px; border:0; border-radius:24px; background:var(--terracotta); color:#fff; font-weight:800; font-size:14px; cursor:pointer;}
  .visual-search .vs-explore:hover{background:var(--terracotta-dark);}
  .visual-search input[type=date]{color:#667085;}
  .visual-search input[type=date]::-webkit-calendar-picker-indicator{opacity:.65; cursor:pointer;}
  @media(max-width:900px){
    .visual-home-hero{height:620px; min-height:620px; padding:0 !important; background-size:auto 468px; background-position:center top; background-color:#f8f3e9;}
    .visual-search{left:5% !important; right:5% !important; top:auto !important; bottom:20px; grid-template-columns:1fr 1fr !important; border-radius:20px !important;}
    .visual-search-field:nth-child(2){border-right:0;}
    .visual-search-field:nth-child(3){border-top:1px solid rgba(27,42,69,.12);}
    .visual-search .vs-explore{min-height:48px;}
  }
  @media(max-width:560px){
    .visual-home-hero{height:740px; min-height:740px; padding:0 !important; background-size:auto 468px; background-position:center top; background-color:#f8f3e9;}
    .visual-search{grid-template-columns:1fr !important; bottom:16px;}
    .visual-search-field{border-right:0 !important; border-bottom:1px solid rgba(27,42,69,.12);}
    .visual-search .vs-explore{width:100%; min-height:46px;}
  }

  /* ---------- SECTION BASE ---------- */
  section{padding:78px 0;}
  section.alt{background:var(--sage);}
  section.dark{background:var(--navy); color:#fff;}
  section.dark h2, section.dark h3{color:#fff;}
  section.dark p{color:rgba(255,255,255,0.7);}
  .section-head{max-width:640px; margin-bottom:40px;}
  .section-head.center{margin-left:auto; margin-right:auto; text-align:center;}

  /* ---------- FILTER BAR ---------- */
  .filter-panel{
    background:#fff; border:1px solid var(--line); border-radius:18px; padding:28px;
    box-shadow:0 20px 50px -30px rgba(27,42,69,0.3); margin-top:-90px; position:relative; z-index:5;
  }
  .visual-home-hero + .wrap #filterPanel{margin-top:0;}
  .filter-grid{display:grid; grid-template-columns:repeat(4, 1fr); gap:18px; margin-bottom:20px;}
  .filter-field label{
    display:block; font-family:'JetBrains Mono', monospace; font-size:10.5px; letter-spacing:0.08em;
    text-transform:uppercase; color:var(--text-dim); margin-bottom:8px; font-weight:600;
  }
  .filter-field select{
    width:100%; padding:11px 14px; border-radius:9px; border:1.5px solid var(--line);
    font-family:inherit; font-size:14px; color:var(--navy); background:#fff url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="10" height="6"><path d="M0 0l5 6 5-6z" fill="%235B6472"/></svg>') no-repeat right 14px center;
    appearance:none; cursor:pointer;
  }
  .chip-row{display:flex; gap:10px; flex-wrap:wrap;}
  .chip{
    padding:9px 16px; border-radius:999px; border:1.5px solid var(--line); font-size:13px; font-weight:600;
    color:var(--navy); background:#fff; cursor:pointer; transition:all .15s ease;
  }
  .chip.on{background:var(--navy); border-color:var(--navy); color:#fff;}
  .filter-footer{display:flex; justify-content:space-between; align-items:center; margin-top:22px; padding-top:20px; border-top:1px solid var(--line); flex-wrap:wrap; gap:14px;}
  .filter-result-count{font-size:13px; color:var(--text-dim); font-weight:600;}

  @media (max-width:900px){
    .filter-grid{grid-template-columns:repeat(2,1fr);}
    .filter-panel{margin-top:-60px;}
  }
  @media (max-width:560px){
    .filter-grid{grid-template-columns:1fr;}
  }

  /* ---------- DESTINATION GRID ---------- */
  .dest-grid{display:grid; grid-template-columns:repeat(3, 1fr); gap:24px;}
  @media (max-width:960px){.dest-grid{grid-template-columns:repeat(2,1fr);}}
  @media (max-width:640px){.dest-grid{grid-template-columns:1fr;}}

  .dest-card{
    background:#fff; border:1px solid var(--line); border-radius:var(--radius); overflow:hidden;
    display:flex; flex-direction:column; cursor:pointer; transition:transform .18s ease, box-shadow .18s ease;
  }
  .dest-card:hover{transform:translateY(-4px); box-shadow:0 24px 44px -20px rgba(27,42,69,0.28);}
  .dest-img{height:190px; position:relative; overflow:hidden; background:var(--sage);}
  .dest-img img{width:100%; height:100%; object-fit:cover;}
  .dest-tags{position:absolute; top:12px; left:12px; display:flex; gap:6px; flex-wrap:wrap; max-width:90%;}
  .dest-tags span{
    background:rgba(255,255,255,0.92); color:var(--navy); font-size:10px; font-weight:700;
    padding:4px 9px; border-radius:999px; text-transform:uppercase; letter-spacing:0.03em;
  }
  .dest-rating{
    position:absolute; top:12px; right:12px; background:rgba(27,42,69,0.85); color:#fff;
    font-size:11.5px; font-weight:700; padding:4px 9px; border-radius:999px; display:flex; align-items:center; gap:4px;
  }
  .dest-name-overlay{position:absolute; bottom:0; left:0; right:0; padding:16px; background:linear-gradient(180deg, transparent, rgba(0,0,0,0.65));}
  .dest-name-overlay h3{color:#fff; font-size:21px; font-weight:800;}
  .dest-body{padding:16px 18px 18px;}
  .dest-region{color:var(--terracotta); font-weight:700; font-size:12.5px; margin-bottom:6px;}
  .dest-desc{font-size:13px; margin-bottom:14px; min-height:38px;}
  .dest-meta-row{display:flex; justify-content:space-between; align-items:center; font-size:12.5px; color:var(--text-dim); margin-bottom:14px; font-weight:600;}
  .dest-price{color:var(--navy); font-weight:800; font-size:15px;}
  .dest-price small{font-weight:500; color:var(--text-dim); font-size:11px;}

  /* ---------- WHY GHOOMO 3-STEP ---------- */
  .step-grid{display:grid; grid-template-columns:repeat(3,1fr); gap:22px; margin-top:36px;}
  @media (max-width:800px){.step-grid{grid-template-columns:1fr;}}
  .step-card{background:rgba(255,255,255,0.06); border:1px solid rgba(255,255,255,0.14); border-radius:16px; padding:26px;}
  section.dark .step-card .step-num{font-family:'JetBrains Mono',monospace; color:var(--gold); font-size:13px; font-weight:700; margin-bottom:12px;}

  /* ---------- FOOTER ---------- */
  footer{background:var(--navy-2); color:rgba(255,255,255,0.65); padding:50px 0 26px;}
  .footer-top{display:flex; justify-content:space-between; flex-wrap:wrap; gap:30px; margin-bottom:34px;}
  .footer-logo{height:32px; margin-bottom:14px;}
  .footer-cols{display:flex; gap:60px; flex-wrap:wrap;}
  .footer-col h4{color:#fff; font-size:13px; margin-bottom:14px; letter-spacing:0.04em;}
  .footer-col a{display:block; font-size:13.5px; margin-bottom:9px; color:rgba(255,255,255,0.65);}
  .footer-col a:hover{color:var(--gold);}
  .footer-bottom{border-top:1px solid rgba(255,255,255,0.12); padding-top:20px; font-size:12px; display:flex; justify-content:space-between; flex-wrap:wrap; gap:10px;}

  /* ---------- DESTINATION PAGE ---------- */
  .dest-hero{position:relative; height:360px; background-size:cover; background-position:center; display:flex; align-items:flex-end;}
  .dest-hero::before{content:''; position:absolute; inset:0; background:linear-gradient(180deg, rgba(15,20,35,0.15), rgba(15,20,35,0.82));}
  .dest-hero-content{position:relative; z-index:2; padding:36px 28px; max-width:1200px; margin:0 auto; width:100%;}
  .dest-hero-content h1{color:#fff; margin-bottom:8px;}
  .dest-hero-content .sub{color:rgba(255,255,255,0.85); font-size:14.5px;}
  .dest-hero-tags{display:flex; gap:8px; margin-bottom:14px; flex-wrap:wrap;}
  .dest-hero-tags span{background:rgba(255,255,255,0.16); color:#fff; font-size:11px; font-weight:700; padding:5px 12px; border-radius:999px; border:1px solid rgba(255,255,255,0.3);}
  .back-link{display:inline-flex; align-items:center; gap:6px; color:var(--terracotta); font-weight:700; font-size:13.5px; margin-bottom:20px;}

  .style-tabs{display:flex; gap:12px; flex-wrap:wrap; margin-bottom:30px;}
  .style-tab{
    flex:1; min-width:160px; padding:16px 18px; border-radius:12px; border:1.5px solid var(--line); background:#fff; cursor:pointer;
  }
  .style-tab.on{border-color:var(--terracotta); background:rgba(193,96,46,0.06);}
  .style-tab .t{font-weight:700; font-size:14.5px; margin-bottom:3px;}
  .style-tab .d{font-size:12px; color:var(--text-dim);}

  .itin-scroll{display:flex; gap:16px; overflow-x:auto; padding-bottom:10px;}
  .itin-card{
    min-width:200px; background:#fff; border:1px solid var(--line); border-radius:12px; padding:18px; flex-shrink:0;
  }
  .itin-card .d-num{font-family:'JetBrains Mono',monospace; color:var(--terracotta); font-weight:700; font-size:12px; margin-bottom:8px;}
  .itin-card .d-title{font-weight:700; font-size:14.5px; margin-bottom:6px;}
  .itin-card .d-desc{font-size:12.5px; color:var(--text-dim); line-height:1.5;}

  .cat-selector{display:flex; gap:12px; flex-wrap:wrap; margin-bottom:28px;}
  .cat-card{
    flex:1; min-width:220px; padding:18px 20px; border-radius:14px; border:1.5px solid var(--line);
    background:#fff; cursor:pointer; display:flex; gap:12px; align-items:flex-start;
  }
  .cat-card.on{border-color:var(--navy); background:var(--navy); }
  .cat-card.on .cat-title, .cat-card.on .cat-desc{color:#fff;}
  .cat-icon{width:36px; height:36px; border-radius:9px; background:var(--sage); display:flex; align-items:center; justify-content:center; font-size:16px; flex-shrink:0;}
  .cat-title{font-weight:700; font-size:14.5px; margin-bottom:2px;}
  .cat-desc{font-size:12px; color:var(--text-dim);}

  .compare-table-wrap{background:#fff; border:1px solid var(--line); border-radius:16px; overflow-x:auto; margin-bottom:20px;}
  table.compare{width:100%; border-collapse:collapse; min-width:760px;}
  table.compare th, table.compare td{text-align:left; padding:15px 18px; font-size:13px; border-bottom:1px solid var(--line); white-space:nowrap;}
  table.compare thead th{background:var(--navy); color:#fff; font-size:11px; letter-spacing:0.04em; text-transform:uppercase; font-family:'JetBrains Mono',monospace; position:sticky; top:0;}
  table.compare td.row-label{
    font-family:'JetBrains Mono',monospace; font-size:11px; letter-spacing:0.04em; text-transform:uppercase;
    color:var(--text-dim); background:var(--sage); font-weight:700; position:sticky; left:0;
  }
  table.compare tbody tr:last-child td{border-bottom:none;}
  .provider-cell{display:flex; flex-direction:column; gap:2px;}
  .provider-badge{
    width:34px; height:34px; border-radius:8px; display:flex; align-items:center; justify-content:center;
    color:#fff; font-weight:800; font-size:12px; margin-bottom:6px;
  }
  .provider-name{font-weight:700; font-size:13px; color:var(--navy);}
  .view-btn{
    background:var(--terracotta); color:#fff; font-size:12px; font-weight:700; padding:7px 14px; border-radius:999px; display:inline-block;
  }
  .provider-logo{width:34px;height:34px;border-radius:8px;object-fit:contain;background:#fff;padding:4px;display:block;}
  .provider-badge.logo-wrap{background:#fff;overflow:hidden;}
  .provider-logo-fallback{width:34px;height:34px;border-radius:8px;display:grid;place-items:center;background:var(--sage);color:var(--navy);font-size:11px;font-weight:800;}
  .co2-save{display:inline-flex;align-items:center;gap:4px;background:#EEF6EF;color:#236B3A;padding:5px 8px;border-radius:8px;font-size:11px;font-weight:800;}
  .partner-pending{font-size:11px;color:var(--text-dim);font-weight:700;}
  .view-btn{cursor:pointer;text-decoration:none;}
  .compare-layout{display:grid;grid-template-columns:250px minmax(0,1fr);gap:22px;align-items:start;}
  .compare-sidebar{background:#fff;border:1px solid var(--line);border-radius:16px;padding:18px;position:sticky;top:92px;box-shadow:0 14px 34px -24px rgba(27,42,69,.28);}
  .compare-sidebar h3{font-size:15px;margin-bottom:6px;}
  .compare-sidebar p{font-size:12px;margin-bottom:14px;}
  .compare-sidebar label{display:block;font-size:11px;font-weight:800;color:var(--text-dim);text-transform:uppercase;letter-spacing:.06em;margin:12px 0 6px;}
  .compare-sidebar select{width:100%;padding:10px;border:1px solid var(--line);border-radius:9px;background:#fff;color:var(--navy);font-family:inherit;}
  .provider-pick{display:flex;align-items:flex-start;gap:8px;font-size:12px;color:var(--navy);margin:9px 0;line-height:1.35;}
  .provider-pick input{accent-color:var(--terracotta);margin-top:2px;}
  .selection-count{font-size:11px;font-weight:800;color:var(--terracotta);margin-top:12px;}
  .compare-main{min-width:0;}
  .compare-sidebar select[multiple]{width:100%;padding:10px;border:1px solid var(--line);border-radius:10px;background:#fff;color:var(--navy);font:inherit;min-height:150px;}
  .image-fallback{background:linear-gradient(135deg,#ead7b4,#c1602e 52%,#1b2a45);}
  @media (max-width:900px){.compare-layout{grid-template-columns:1fr;}.compare-sidebar{position:static;}.compare-sidebar .provider-options{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 14px;}}

  .price-cell{font-weight:800; color:var(--navy); font-size:14px;}
  .disclaimer-note{font-size:12px; color:var(--text-dim); background:var(--sage); border-radius:10px; padding:14px 18px; margin-bottom:50px;}

  /* ---------- ABOUT PAGE ---------- */
  .about-hero{padding:70px 0 50px; text-align:center;}
  .model-grid{display:grid; grid-template-columns:repeat(3,1fr); gap:20px; margin:40px 0;}
  @media (max-width:800px){.model-grid{grid-template-columns:1fr;}}
  .model-card{background:#fff; border:1px solid var(--line); border-radius:14px; padding:24px;}
  .model-card .icon{width:42px; height:42px; border-radius:10px; background:var(--sage); display:flex; align-items:center; justify-content:center; font-size:19px; margin-bottom:14px;}

  /* toast */
  .toast{
    position:fixed; bottom:26px; left:50%; transform:translateX(-50%) translateY(20px); opacity:0;
    background:var(--navy); color:#fff; padding:13px 22px; border-radius:999px; font-size:13.5px; font-weight:600;
    box-shadow:0 20px 40px -10px rgba(0,0,0,0.4); z-index:300; transition:all .25s ease; pointer-events:none;
  }
  .toast.show{opacity:1; transform:translateX(-50%) translateY(0);}

  .hidden{display:none !important;}
  @media (max-width:700px){
    .filter-grid{grid-template-columns:1fr 1fr;}
    .dest-hero{height:280px;}
  }



/* Explore India: detailed 2D map controls (staging) */
.india-svg-map .india-map-toolbar{display:flex;gap:8px;justify-content:flex-end;padding:8px 10px 2px}
.india-svg-map .india-map-toolbar button{min-width:42px;min-height:42px;border:1px solid #b6c9bf;border-radius:10px;background:#fff;color:#0f2e6d;font-weight:800;cursor:pointer}
.india-svg-map .india-map-toolbar button:focus-visible,.india-svg-map .india-map-shape:focus-visible{outline:3px solid #e76f2c;outline-offset:2px}
.india-svg-map .india-map-viewport{overflow:hidden;max-width:100%}
.india-svg-map .india-map-help{padding:2px 12px 12px;color:#40566b;font-size:12px;line-height:1.5}
.india-svg-map .india-boundary-svg{display:block;width:100%;height:auto;max-height:650px}
.india-svg-map .india-map-shape{cursor:pointer;stroke:#ffffff;stroke-width:1.2;vector-effect:non-scaling-stroke}
.india-svg-map .india-map-shape:hover,.india-svg-map .india-map-shape.hovered{stroke:#e76f2c;stroke-width:2.2}
/* Tourism India: compact realistic attraction preview and accessible actions */
.ghoomo-tourism-card{position:relative;margin:12px 10px 16px;padding:14px;background:#fffaf2;border:1px solid #e7d5b8;border-radius:18px;box-shadow:0 8px 24px rgba(15,46,109,.12);color:#18314b}
.ghoomo-tourism-card-head{display:flex;align-items:center;justify-content:space-between;gap:12px;color:#566778;font-size:11px;font-weight:800;letter-spacing:.06em}
.ghoomo-tourism-card-head button{border:0;background:#eef2f5;color:#142b45;border-radius:50%;font-size:22px;width:40px;height:40px;cursor:pointer}
.ghoomo-tourism-photo{margin-top:8px;height:170px;border-radius:14px;background:linear-gradient(140deg,#dcefe4,#e8eff8);display:flex;align-items:center;justify-content:center;overflow:hidden;font-size:65px;box-shadow:0 8px 15px rgba(0,0,0,.12)}
.ghoomo-tourism-photo img{width:100%;height:100%;object-fit:cover}
.ghoomo-tourism-card h3{margin:10px 0 0;font-size:20px}.ghoomo-tourism-place{font-weight:700;color:#a24b1f;margin:3px 0 9px}
.ghoomo-tourism-narration{font-size:14px;line-height:1.65}.ghoomo-tourism-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}
.ghoomo-tourism-actions button{min-height:44px;border:0;border-radius:10px;background:#0f2e6d;color:white;padding:9px 13px;font-weight:700;cursor:pointer}
.ghoomo-tourism-credit{display:block;margin-top:10px;color:#617080;font-size:11px;line-height:1.5}
.ghoomo-tourism-credit a{color:#164f86;text-decoration:underline}
.india-tourism-mini-marker{font-size:15px;paint-order:stroke;stroke:#fff;stroke-width:2px;pointer-events:none}
@media(prefers-reduced-motion:reduce){.ghoomo-tourism-card{animation:none!important;transition:none!important}}
